diff --git a/src/main/java/com/networknt/schema/format/AbstractRFC3986Format.java b/src/main/java/com/networknt/schema/format/AbstractRFC3986Format.java
index 0b0748b5..2500d88e 100644
--- a/src/main/java/com/networknt/schema/format/AbstractRFC3986Format.java
+++ b/src/main/java/com/networknt/schema/format/AbstractRFC3986Format.java
@@ -4,0 +5 @@ import java.net.URISyntaxException;
+import java.util.regex.Pattern;
@@ -12,0 +14,2 @@ public abstract class AbstractRFC3986Format implements Format {
+    private static final Pattern VALID = Pattern.compile("([A-Za-z0-9+-\\.]*:)?//|[A-Za-z0-9+-\\.]+:");
+
@@ -19 +22 @@ public abstract class AbstractRFC3986Format implements Format {
-            return false;
+            return handleException(e);
@@ -30,0 +34,12 @@ public abstract class AbstractRFC3986Format implements Format {
+    /**
+     * Determines if the uri matches the format.
+     *
+     * @param e the URISyntaxException
+     * @return false if it does not match
+     */
+    protected boolean handleException(URISyntaxException e) {
+        if (VALID.matcher(e.getInput()).matches()) {
+            return true;
+        }
+        return false;
+    }
